// Manor's color roles, originally generated from the web tokens. Light and dark are tuned independently and every
// text and control pairing is checked for WCAG contrast (4.5:1 text, 3:1 control edges) in both themes.
import AppKit
import SwiftUI

extension Color {
  fileprivate static func manor(_ light: (Double, Double, Double, Double), _ dark: (Double, Double, Double, Double), contrastBoost: Double = 0) -> Color {
    Color(nsColor: NSColor(name: nil) { appearance in
      let isDark = appearance.bestMatch(from: [.darkAqua, .aqua, .accessibilityHighContrastDarkAqua, .accessibilityHighContrastAqua])
        .map { $0 == .darkAqua || $0 == .accessibilityHighContrastDarkAqua } ?? false
      var v = isDark ? dark : light
      // Increase Contrast pulls text, borders, and hairlines toward full contrast and makes them opaque.
      if contrastBoost > 0, NSWorkspace.shared.accessibilityDisplayShouldIncreaseContrast {
        let target = isDark ? 1.0 : 0.0
        v = (v.0 + (target - v.0) * contrastBoost, v.1 + (target - v.1) * contrastBoost, v.2 + (target - v.2) * contrastBoost, 1)
      }
      return NSColor(srgbRed: v.0, green: v.1, blue: v.2, alpha: v.3)
    })
  }
}

